package com.cyclecare.app
import com.cyclecare.app.data.local.rust.*
import org.junit.Assert.*
import org.junit.Test
class ResolutionStorageJniBoundaryTest{
 open class Probe(val data:LongArray=longArrayOf(1,7,7,9,0,0),val matched:Boolean=true,val cut:Int=0,val error:Throwable=IllegalStateException("sentinel")){val trace=mutableListOf<String>();private val thread=Thread.currentThread();private fun hit(s:String){assertSame(thread,Thread.currentThread());trace+=s;if(trace.size==cut)throw error};open fun ready(){hit("ready")};fun metadata():LongArray{hit("metadata");return data};fun hashMatches():Boolean{hit("hash");return matched};fun skip(){hit("skip")};fun prepare(n:Long,r:Boolean){assertEquals(data[1]+1,n);assertEquals(data[5]==1L,r);hit("prepare")};fun domain(){hit("domain")};fun delete(){hit("delete")};fun revision(n:Long){assertEquals(data[1]+1,n);hit("revision")};fun outbox(){hit("outbox")};fun resolve(){hit("resolve")}}
 @Test fun exactBothBranchesEveryThrowableCutoffAndSkipShortCircuit(){RustTrackNative.warmUp();for(retain in 0L..1L){val data=longArrayOf(1,7,7,9,0,retain);val expected=if(retain==1L)listOf("ready","metadata","hash","prepare","delete","revision","outbox","resolve")else listOf("ready","metadata","hash","prepare","domain","delete","revision","resolve");val p=Probe(data);assertEquals(1,RustTrackNative.resolutionDriver(p));assertEquals(expected,p.trace);for(error in listOf(IllegalArgumentException("sentinel"),ArithmeticException("sentinel"),kotlinx.coroutines.CancellationException("sentinel"),AssertionError("sentinel")))for(cut in 1..expected.size){val q=Probe(data,cut=cut,error=error);assertSame(error,runCatching{RustTrackNative.resolutionDriver(q)}.exceptionOrNull());assertEquals(expected.take(cut),q.trace)}};for(data in listOf(longArrayOf(),longArrayOf(1,7,8,9,0,0),longArrayOf(0,0,1,9,0,0),longArrayOf(0,0,0,9,0,1))){val p=Probe(data);assertEquals(0,RustTrackNative.resolutionDriver(p));assertEquals(listOf("ready","metadata","skip"),p.trace)};val p=Probe(matched=false);assertEquals(0,RustTrackNative.resolutionDriver(p));assertEquals(listOf("ready","metadata","hash","skip"),p.trace)}
 @Test fun signedDomainsOverflowBeforePolicyExactRejectAndMetadataFailClosed(){RustTrackNative.warmUp();for(retain in 0L..1L){for(local in listOf(Long.MIN_VALUE,-1L,0L,Long.MAX_VALUE-1)){assertEquals(1,RustTrackNative.resolutionDriver(Probe(longArrayOf(1,local,local,if(retain==1L)0 else Long.MAX_VALUE,0,retain))))};val p=Probe(longArrayOf(1,Long.MAX_VALUE,Long.MAX_VALUE,-1,1,retain));val e=runCatching{RustTrackNative.resolutionDriver(p)}.exceptionOrNull();assertTrue(e is ArithmeticException);assertEquals("long overflow",e?.message);assertEquals(listOf("ready","metadata","hash"),p.trace);for(remote in listOf(Long.MIN_VALUE,-1L,0L)){val q=Probe(longArrayOf(1,7,7,remote,0,retain));if(retain==1L&&remote==0L)assertEquals(1,RustTrackNative.resolutionDriver(q))else{val reject=runCatching{RustTrackNative.resolutionDriver(q)}.exceptionOrNull();assertTrue(reject is ConflictRejected);assertEquals("remote_record_missing_accept_unavailable",reject?.message);assertEquals(listOf("ready","metadata","hash"),q.trace)}}};val e=runCatching{RustTrackNative.resolutionDriver(Probe(longArrayOf(1,7,7,0,1,1)))}.exceptionOrNull();assertTrue(e is ConflictRejected);assertEquals("keep_local_unavailable_server_tombstone",e?.message);for(data in listOf(longArrayOf(1),longArrayOf(2,7,7,9,0,0),longArrayOf(1,7,7,9,-1,0),longArrayOf(1,7,7,9,0,2))){val p=Probe(data);assertTrue(runCatching{RustTrackNative.resolutionDriver(p)}.exceptionOrNull()is IllegalStateException);assertEquals(listOf("ready","metadata"),p.trace)}}
 @Test fun missingCallbackAndNoGlobalMonitor(){RustTrackNative.warmUp();assertTrue(runCatching{RustTrackNative.resolutionDriver(Any())}.exceptionOrNull()is NoSuchMethodError);val p=object:Probe(){override fun ready(){val latch=java.util.concurrent.CountDownLatch(1);val t=Thread{synchronized(RustTrackNative){latch.countDown()}};t.start();assertTrue(latch.await(2,java.util.concurrent.TimeUnit.SECONDS));t.join();super.ready()}};assertEquals(1,RustTrackNative.resolutionDriver(p))}
}
